SELECT SUM(day1.show_pv) show_pv,
       SUM(day1.click_pv) click_pv,
       SUM(day1.req_pv) req_pv,
       SUM(day1.discard) discard,
       SUM(day1.ret_pv) ret_pv,
       SUM(day1.spend) spend,
       SUM(day1.income) income
FROM data_dsp_slot_day day1
LEFT JOIN dsp_slot_info dsp ON day1.dsp_slot_id = dsp.id
LEFT JOIN dsp_company com ON dsp.company_id = com.id

  day1.date BETWEEN #{reqVO.date[0]} AND #{reqVO.date[1]}
  AND com.id = #{reqVO.companyId}
  AND dsp.product_id IN #{id}
  AND day1.dsp_slot_id IN #{id}
  AND day1.dsp_slot_code IN #{code}
  AND dsp.os_type = #{reqVO.osType}

SELECT
day1.dsp_slot_id AS dsp_slot_id, day1.date AS date, SUM(day1.show_pv) AS show_pv, SUM(day1.click_pv) AS click_pv, SUM(day1.req_pv) AS req_pv, SUM(day1.discard) AS discard, SUM(day1.ret_pv) AS ret_pv, SUM(day1.spend) AS spend, SUM(day1.income) AS income, SUM(day1.discount_click_pv) AS discount_click_pv, SUM(day1.discount_show_pv) AS discount_show_pv, SUM(day1.dplsucc_pv) AS dplsucc_pv, SUM(day1.complete_pv) AS complete_pv, SUM(day1.install_pv) AS install_pv, SUM(day1.activate_pv) AS activate_pv,
MAX(day1.dsp_slot_code) AS dspSlotCode, MAX(day1.ssp_slot_id) AS sspSlotId, MAX(dsp.name) AS dspName, MAX(com.name) AS companyName, MAX(pro.name) AS productName, MAX(ssp.name_alise) AS sspName, MAX(app.name) AS appName, MAX(app.os_type) AS osType, MAX(media.media_company_short) AS mediaName
FROM data_dsp_slot_day AS day1 LEFT JOIN dsp_slot_info AS dsp ON dsp.id = day1.dsp_slot_id LEFT JOIN dsp_company AS com ON com.id = dsp.company_id LEFT JOIN dsp_product AS pro ON pro.id = dsp.product_id LEFT JOIN ssp_slot_info AS ssp ON ssp.id = day1.ssp_slot_id LEFT JOIN ssp_app AS app ON app.id = ssp.app_id LEFT JOIN ssp_media AS media ON media.id = ssp.media_id
AND day1.date BETWEEN REPLACE(#{reqVO.date[0]}, '-', '') AND REPLACE(#{reqVO.date[1]}, '-', '')
AND day1.dsp_slot_id IN
#{id}
AND day1.dsp_slot_code IN
#{code}
AND day1.dsp_slot_code = #{reqVO.dspSlotCode}
AND day1.ssp_slot_id IN
#{id}
AND dsp.company_id = #{reqVO.companyId}
AND dsp.product_id IN
#{id}
AND app.os_type = #{reqVO.osType}
GROUP BY day1.dsp_slot_id, day1.date
ORDER BY day1.date DESC

SELECT day1.*, dsp.name AS dspName, dsp.dsp_slot_code AS dspSlotCode, dsp.ad_scene AS dspAdScene, dsp.os_type AS dspOsType, com.name AS companyName, pro.name AS productName, ssp.name AS sspSlotName, ssp.name_alise AS sspName, ssp.ad_scene AS sspAdScene, app.name AS appName, app.os_type AS osType, media.media_company_short AS mediaName
FROM data_dsp_slot_day AS day1 LEFT JOIN dsp_slot_info AS dsp ON dsp.id = day1.dsp_slot_id LEFT JOIN dsp_company AS com ON com.id = dsp.company_id LEFT JOIN dsp_product AS pro ON pro.id = dsp.product_id LEFT JOIN ssp_slot_info AS ssp ON ssp.id = day1.ssp_slot_id LEFT JOIN ssp_app AS app ON app.id = ssp.app_id LEFT JOIN ssp_media AS media ON media.id = ssp.media_id
AND day1.date BETWEEN REPLACE(#{reqVO.date[0]}, '-', '') AND REPLACE(#{reqVO.date[1]}, '-', '')
AND day1.dsp_slot_id IN
#{id}
AND day1.dsp_slot_code IN
#{code}
AND day1.dsp_slot_code = #{reqVO.dspSlotCode}
AND day1.ssp_slot_id IN
#{id}
AND dsp.company_id = #{reqVO.companyId}
AND dsp.product_id IN
#{id}
AND app.os_type = #{reqVO.osType}
ORDER BY day1.date DESC

SELECT day1.date AS date, SUM(day1.req_pv) AS req_pv, SUM(day1.ret_pv) AS ret_pv, SUM(day1.show_pv) AS show_pv, SUM(day1.click_pv) AS click_pv, SUM(day1.spend) AS spend, SUM(day1.income) AS income FROM data_dsp_slot_day AS day1 LEFT JOIN dsp_slot_info AS dsp ON dsp.id = day1.dsp_slot_id LEFT JOIN dsp_company AS com ON com.id = dsp.company_id LEFT JOIN dsp_product AS pro ON pro.id = dsp.product_id LEFT JOIN ssp_slot_info AS ssp ON ssp.id = day1.ssp_slot_id LEFT JOIN ssp_app AS app ON app.id = ssp.app_id
AND day1.date BETWEEN REPLACE(#{reqVO.date[0]}, '-', '') AND REPLACE(#{reqVO.date[1]}, '-', '')
AND day1.dsp_slot_id IN
#{id}
AND day1.dsp_slot_code IN
#{code}
AND day1.dsp_slot_code = #{reqVO.dspSlotCode}
AND day1.ssp_slot_id IN
#{id}
AND dsp.company_id = #{reqVO.companyId}
AND dsp.product_id IN
#{id}
AND app.os_type = #{reqVO.osType}
GROUP BY day1.date ORDER BY day1.date ASC

SELECT day.*
FROM data_dsp_slot_day AS day
WHERE day.id = #{id}

SELECT d.*
FROM data_dsp_slot_day AS d
WHERE d.dsp_slot_code = #{dspSlotCode}
  AND d.date = #{inputTime}
  AND d.deleted = 0
ORDER BY d.id DESC

